    LinearLayout compactDays(LinearLayout host){ host.addView(label("Patch days")); LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.HORIZONTAL);String[] names={"MON","TUE","WED","THU","FRI","SAT","SUN"};String saved=State.p(this).getString("patchDays","TUE,SAT");for(String n:names){CheckBox c=new CheckBox(this);c.setText(n);c.setTextSize(11);c.setChecked(saved.contains(n));box.addView(c,new LinearLayout.LayoutParams(0,dp(48),1));}host.addView(box);return box; }
    NumberPicker wheelIn(LinearLayout host,String name,int min,int max,int value){host.addView(label(name));NumberPicker p=new NumberPicker(this);p.setMinValue(min);p.setMaxValue(max);p.setValue(Math.max(min,Math.min(max,value)));p.setWrapSelectorWheel(true);host.addView(p,new LinearLayout.LayoutParams(-1,dp(82)));return p;}
    SideWheel smallWheel(LinearLayout host,String name,int min,int max,int value){LinearLayout col=new LinearLayout(this);col.setOrientation(LinearLayout.VERTICAL);col.setGravity(Gravity.CENTER_HORIZONTAL);TextView l=tv(name,11);l.setTextColor(purple);l.setGravity(Gravity.CENTER);col.addView(l);SideWheel p=new SideWheel(min,max,Math.max(min,Math.min(max,value)),false);col.addView(p,new LinearLayout.LayoutParams(dp(128),dp(70)));host.addView(col,new LinearLayout.LayoutParams(0,dp(86),1));return p;}
    LinearLayout sectionCard(String title,String subtitle){ LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(8),dp(14),dp(8));card.setBackground(bg(Color.WHITE,16));TextView h=tv(title,19);h.setTypeface(null,1);card.addView(h);TextView s=tv(subtitle,13);s.setTextColor(muted);card.addView(s);root.addView(card);gap(6);return card; }
    void showSetup(){ base(); gap(6); TextView h=tv("Schedule",28);h.setTypeface(null,1);root.addView(h);root.addView(tv("Set each part of your hormone plan separately.",14));gap(12);
        LinearLayout cycleCard=sectionCard("Cycle","Length and current position");LinearLayout cycleRow=new LinearLayout(this);cycleRow.setGravity(Gravity.CENTER);cycleCard.addView(cycleRow);SideWheel cycle=smallWheel(cycleRow,"Length · days",1,60,State.cycle(this));SideWheel today=smallWheel(cycleRow,"Today · day",1,60,Math.min(State.day(this),State.cycle(this)));
        LinearLayout patchCard=sectionCard("Patch","Patch days and patch reminder time");LinearLayout days=compactDays(patchCard);LinearLayout patchClock=compactClock(patchCard,"Patch time",State.p(this).getString("patchTime","10:00"));
        LinearLayout progCard=sectionCard("Progesterone","Start/end days and progesterone reminder time");LinearLayout progRow=new LinearLayout(this);progRow.setGravity(Gravity.CENTER);progCard.addView(progRow);SideWheel ps=smallWheel(progRow,"Starts · day",1,60,Math.min(State.p(this).getInt("progStart",15),State.cycle(this)));SideWheel pe=smallWheel(progRow,"Stops · day",1,60,Math.min(State.p(this).getInt("progEnd",26),State.cycle(this)));LinearLayout progClock=compactClock(progCard,"Progesterone time",State.p(this).getString("progTime","22:00")); cycle.onChanged(()->{int max=cycle.getValue();today.setMaxValue(max);ps.setMaxValue(max);pe.setMaxValue(max);}); today.setMaxValue(cycle.getValue()); ps.setMaxValue(cycle.getValue()); pe.setMaxValue(cycle.getValue()); final int[] acceptedDay={State.day(this)};today.onChanged(()->{int next=today.getValue();int previous=acceptedDay[0];if(next!=previous)confirmCycleDayChange(previous,next,()->{today.value=previous;today.render();},()->acceptedDay[0]=next);});
        LinearLayout checks=sectionCard("Daily check-in","Choose which daily health rows you want to record.");Switch bleeding=checkSwitch(checks,"Bleeding · spotting / light / medium / heavy",State.trackBleeding(this));Switch pain=checkSwitch(checks,"Pain · rate 1–10",State.trackPain(this));Switch mood=checkSwitch(checks,"Mood · rate 1–10",State.trackMood(this));Switch overall=checkSwitch(checks,"Overall feeling · rate 1–10",State.trackOverall(this));bleeding.setOnCheckedChangeListener((b,on)->{State.p(this).edit().putBoolean("trackBleeding",on).apply();ReminderReceiver.schedule(this);});pain.setOnCheckedChangeListener((b,on)->{State.p(this).edit().putBoolean("trackPain",on).apply();ReminderReceiver.schedule(this);});mood.setOnCheckedChangeListener((b,on)->{State.p(this).edit().putBoolean("trackMood",on).apply();ReminderReceiver.schedule(this);});overall.setOnCheckedChangeListener((b,on)->{State.p(this).edit().putBoolean("trackOverall",on).apply();ReminderReceiver.schedule(this);});LinearLayout checkinClock=compactClock(checks,"Daily check-in time",State.p(this).getString("checkinTime","20:00"));
        LinearLayout visible=sectionCard("Cycle map","Choose which rows are visible. Your saved data stays safe.");Switch showPatch=checkSwitch(visible,"Patch",State.showMap(this,"patch"));Switch showProg=checkSwitch(visible,"Progesterone",State.showMap(this,"pill"));Switch showBlood=checkSwitch(visible,"Bleeding",State.showMap(this,"bleeding"));Switch showPain=checkSwitch(visible,"Pain",State.showMap(this,"pain"));Switch showMood=checkSwitch(visible,"Mood",State.showMap(this,"mood"));Switch showOverall=checkSwitch(visible,"Overall",State.showMap(this,"overall"));showPatch.setOnCheckedChangeListener((v,on)->State.p(this).edit().putBoolean("show_patch",on).apply());showProg.setOnCheckedChangeListener((v,on)->State.p(this).edit().putBoolean("show_pill",on).apply());showBlood.setOnCheckedChangeListener((v,on)->State.p(this).edit().putBoolean("show_bleeding",on).apply());showPain.setOnCheckedChangeListener((v,on)->State.p(this).edit().putBoolean("show_pain",on).apply());showMood.setOnCheckedChangeListener((v,on)->State.p(this).edit().putBoolean("show_mood",on).apply());showOverall.setOnCheckedChangeListener((v,on)->State.p(this).edit().putBoolean("show_overall",on).apply());
        Button save=button("Save schedule");save.setTextColor(purple);save.setOnClickListener(v->{int c=cycle.getValue();StringBuilder selected=new StringBuilder();for(int i=0;i<days.getChildCount();i++){CheckBox cb=(CheckBox)days.getChildAt(i);if(cb.isChecked()){if(selected.length()>0)selected.append(",");selected.append(cb.getText());}}State.save(this,c,Math.min(today.getValue(),c),ps.getValue(),pe.getValue(),selected.toString(),clockValue(patchClock),clockValue(progClock),clockValue(checkinClock));State.p(this).edit().putBoolean("trackPain",pain.isChecked()).putBoolean("trackMood",mood.isChecked()).putBoolean("trackOverall",overall.isChecked()).putBoolean("trackBleeding",bleeding.isChecked()).apply();ReminderReceiver.schedule(this);showDashboard();});Button export=button("Export Excel-compatible backup");export.setOnClickListener(v->exportBackup());Button imp=button("Import backup");imp.setOnClickListener(v->importBackup());Button reset=button("Clear all data");reset.setTextColor(Color.rgb(190,55,75));reset.setOnClickListener(v->confirmReset());Button back=button("Cancel");back.setOnClickListener(v->showDashboard());LinearLayout actions=sectionCard("Actions","Save changes or manage your data.");actionButton(actions,save,true);actionButton(actions,export,false);actionButton(actions,imp,false);actionButton(actions,reset,false);actionButton(actions,back,false);gap(14);addDebugTools(); }
    void actionButton(LinearLayout host,Button b,boolean primary){b.setTextSize(14);b.setTextColor(b.getText().toString().startsWith("Reset")?Color.rgb(190,55,75):purple);b.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);b.setPadding(dp(8),0,dp(8),0);b.setMinHeight(dp(40));b.setElevation(0);b.setBackground(bg(primary?Color.rgb(244,241,255):Color.TRANSPARENT,10));host.addView(b,new LinearLayout.LayoutParams(-1,dp(40)));View divider=new View(this);divider.setBackgroundColor(Color.rgb(238,235,244));host.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}
    Switch checkSwitch(LinearLayout host,String title,boolean checked){Switch s=new Switch(this);s.setText(title);s.setTextSize(15);s.setTextColor(ink);s.setPadding(0,0,0,0);s.setMinHeight(dp(38));s.setChecked(checked);host.addView(s,new LinearLayout.LayoutParams(-1,dp(40)));return s;}
    void confirmReset(){new AlertDialog.Builder(this).setTitle("Clear all data?").setMessage("This will erase health checks, confirmations, skipped reminders, cycle history, demo data, and settings. This cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Clear all data",(d,w)->{State.resetAll(this);Toast.makeText(this,"All data cleared",Toast.LENGTH_SHORT).show();showDashboard();}).show();}
    void addDebugTools(){ root.addView(label("Developer tools")); Switch debug=new Switch(this); debug.setText("Enable test reminders"); debug.setTextSize(16); debug.setTextColor(ink); debug.setChecked(State.p(this).getBoolean("debug",false)); root.addView(debug); LinearLayout tests=new LinearLayout(this); tests.setOrientation(LinearLayout.VERTICAL); tests.setVisibility(debug.isChecked()?View.VISIBLE:View.GONE); tests.setPadding(0,dp(8),0,0); Switch demoMode=new Switch(this); demoMode.setText("Use temporary demo data"); demoMode.setTextSize(16); demoMode.setTextColor(ink); demoMode.setChecked(State.p(this).contains("demoBackup")); demoMode.setOnCheckedChangeListener((b,on)->{if(on){State.loadDemoData(this);Toast.makeText(this,"Temporary demo data loaded",Toast.LENGTH_SHORT).show();}else{State.restoreDemoIfNeeded(this);ReminderReceiver.schedule(this);HrtBuddyWidget.refresh(this);Toast.makeText(this,"Real data restored",Toast.LENGTH_SHORT).show();}showDashboard();}); tests.addView(demoMode); Button pill=button("Test progesterone reminder"); pill.setOnClickListener(v->ReminderReceiver.testNotify(this,"pill")); Button patch=button("Test patch reminder"); patch.setOnClickListener(v->ReminderReceiver.testNotify(this,"patch")); Button check=button("Test daily check-in reminder"); check.setOnClickListener(v->ReminderReceiver.testNotify(this,"checkin")); actionButton(tests,pill,false);actionButton(tests,patch,false);actionButton(tests,check,false); root.addView(tests); debug.setOnCheckedChangeListener((b,on)->{State.p(this).edit().putBoolean("debug",on).apply(); tests.setVisibility(on?View.VISIBLE:View.GONE);}); }
    String[] bleedingChoices(LinearLayout card,String saved){String[] selected={saved==null?"":saved};String[] names={"None","Spotting","Light","Medium","Heavy"};int[] colors={Color.rgb(246,244,249),Color.rgb(255,215,215),Color.rgb(249,178,178),Color.rgb(226,108,112),Color.rgb(195,45,58)};LinearLayout choices=new LinearLayout(this);choices.setGravity(Gravity.CENTER);choices.setPadding(0,dp(10),0,dp(4));TextView[] boxes=new TextView[names.length];Runnable refresh=()->{for(int i=0;i<names.length;i++){TextView box=boxes[i];GradientDrawable d=bg(colors[i],8);if(names[i].equals(selected[0]))d.setStroke(dp(3),purple);else d.setStroke(dp(1),Color.WHITE);box.setBackground(d);box.setTextColor(i>3?Color.WHITE:ink);box.setTypeface(null,names[i].equals(selected[0])?1:0);}};for(int i=0;i<names.length;i++){final int picked=i;TextView box=tv(names[i],12);box.setGravity(Gravity.CENTER);box.setOnClickListener(v->{selected[0]=names[picked];refresh.run();});boxes[i]=box;LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(2),0,dp(2),0);choices.addView(box,lp);}card.addView(choices);TextView clear=tv("Not recorded",13);clear.setTextColor(muted);clear.setGravity(Gravity.CENTER);clear.setPadding(0,dp(4),0,dp(8));clear.setOnClickListener(v->{selected[0]="";refresh.run();});card.addView(clear);refresh.run();return selected;}
    void showCheckIn(){ base(); TextView h=tv("Health check",28);h.setTypeface(null,1);root.addView(h);root.addView(tv("A quick snapshot for day "+State.day(this)+".",14));gap(8);LocalDate careDate=State.careDate();SideWheel pain=null,mood=null,overall=null;if(State.trackPain(this))pain=scoreCard("Pain","How much pain today?",State.dailyInt(this,careDate,"pain"));if(State.trackMood(this))mood=scoreCard("Mood","How are you feeling?",State.dailyInt(this,careDate,"mood"));if(State.trackOverall(this))overall=scoreCard("Overall feeling","How is today overall?",State.dailyInt(this,careDate,"overall"));String[] bleeding;if(State.trackBleeding(this)){LinearLayout bleedCard=sectionCard("Bleeding","Choose one for today");bleeding=bleedingChoices(bleedCard,State.dailyText(this,careDate,"bleeding"));}else bleeding=new String[]{""};gap(10);Button save=button("Save health check");save.setTextColor(purple);SideWheel finalPain=pain,finalMood=mood,finalOverall=overall;save.setOnClickListener(v->{State.saveDaily(this,careDate,finalPain==null?-1:finalPain.getValue(),finalMood==null?-1:finalMood.getValue(),finalOverall==null?-1:finalOverall.getValue(),bleeding[0]);State.confirm(this,"checkin");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(ReminderReceiver.notificationId("checkin"));ReminderReceiver.schedule(this);showDashboard();});actionButton(root,save,true);Button back=button("Cancel");back.setOnClickListener(v->showDashboard());actionButton(root,back,false); }
    int scoreColor(int score){return scoreColor("mood",score);}
    int scoreColor(String type,int score){int[] pain={Color.rgb(255,225,225),Color.rgb(255,210,210),Color.rgb(255,195,195),Color.rgb(250,177,177),Color.rgb(246,158,158),Color.rgb(239,139,139),Color.rgb(232,119,119),Color.rgb(224,98,98),Color.rgb(214,75,80),Color.rgb(195,45,58)};int[] wellbeing={Color.rgb(217,79,92),Color.rgb(230,103,106),Color.rgb(240,128,128),Color.rgb(245,154,133),Color.rgb(246,179,106),Color.rgb(233,201,74),Color.rgb(183,201,74),Color.rgb(127,196,107),Color.rgb(85,184,117),Color.rgb(58,170,106)};int[] palette=type.equals("pain")?pain:wellbeing;return palette[Math.max(1,Math.min(10,score))-1];}
    SideWheel scoreCard(String title,String subtitle,int saved){
        LinearLayout card=sectionCard(title,subtitle); SideWheel score=new SideWheel(1,10,saved<1?1:saved,false); score.setVisibility(View.GONE);
        LinearLayout choices=new LinearLayout(this); choices.setGravity(Gravity.CENTER); choices.setPadding(0,dp(10),0,dp(6));
        TextView[] boxes=new TextView[10];
        Runnable refresh=()->{for(int i=0;i<10;i++){TextView box=boxes[i];GradientDrawable d=bg(scoreColor(title.equals("Pain")?"pain":"mood",i+1),8);if(i+1==score.getValue())d.setStroke(dp(3),purple);else d.setStroke(dp(1),Color.WHITE);box.setBackground(d);box.setTextColor(Color.WHITE);box.setTypeface(null,i+1==score.getValue()?1:0);}};
        for(int i=0;i<10;i++){final int picked=i+1;TextView box=tv(String.valueOf(picked),15);box.setGravity(Gravity.CENTER);box.setMinWidth(dp(28));box.setMinHeight(dp(44));box.setOnClickListener(v->{score.value=picked;refresh.run();});boxes[i]=box;LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(44),1);lp.setMargins(dp(2),0,dp(2),0);choices.addView(box,lp);}
        card.addView(choices);refresh.run();return score;
    }
    void showSummary(){ showSummary("patch"); }
    void showSummary(String mode){
        base(); TextView h=tv("Multi-cycle summary",30); h.setTypeface(null,1); root.addView(h); root.addView(tv("Compare your recorded cycles.",16)); gap(10);
        String[] modes={"patch","pill","bleeding","pain","mood","overall"}; String[] names={"Patch","Progesterone","Bleeding","Pain","Mood","Overall feeling"}; java.util.ArrayList<String> availableModes=new java.util.ArrayList<>(); java.util.ArrayList<String> availableNames=new java.util.ArrayList<>(); for(int i=0;i<modes.length;i++){if(tracked(modes[i])||modes[i].equals("patch")||modes[i].equals("pill")){availableModes.add(modes[i]);availableNames.add(names[i]);}} int selectedIndex=Math.max(0,availableModes.indexOf(mode)); TextView parameterLabel=tv("Show parameter",13); parameterLabel.setTextColor(muted); root.addView(parameterLabel); Spinner parameter=new Spinner(this); parameter.setBackground(bg(Color.WHITE,12)); parameter.setPadding(dp(12),0,dp(8),0); ArrayAdapter<String> parameterAdapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,availableNames){@Override public View getView(int position,View convertView,android.view.ViewGroup parent){TextView v=(TextView)super.getView(position,convertView,parent);v.setTextSize(16);v.setTextColor(ink);v.setPadding(dp(12),dp(4),dp(8),dp(4));return v;}}; parameterAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item); parameter.setAdapter(parameterAdapter); parameter.setSelection(selectedIndex); parameter.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> parent,View view,int position,long id){String selected=availableModes.get(position);if(!selected.equals(mode))showSummary(selected);}public void onNothingSelected(android.widget.AdapterView<?> parent){}}); root.addView(parameter,new LinearLayout.LayoutParams(-1,dp(48))); gap(10);
        int n=State.cycle(this); int history=State.historyCycles(this); LinearLayout list=new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); LocalDate start=State.cycleStart(this); for(int cycle=0;cycle<history;cycle++){int length=cycle==0?n:State.cycleLengthAt(this,start); LinearLayout card=new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setPadding(dp(8),dp(2),dp(8),dp(2)); card.setBackground(bg(Color.WHITE,10)); addSummaryHeatRow(card,start,mode,length); list.addView(card); Space sp=new Space(this); list.addView(sp,new LinearLayout.LayoutParams(1,dp(1))); String previous=State.p(this).getString("cycle_prev_"+start,""); if(!previous.isEmpty())try{start=LocalDate.parse(previous);}catch(Exception ignored){start=start.minusDays(length);}else start=start.minusDays(length);} root.addView(list); gap(4); Button back=button("Back to today"); back.setOnClickListener(v->showDashboard()); root.addView(back);
    }
    int num(EditText e,int def){try{return Integer.parseInt(e.getText().toString());}catch(Exception x){return def;}}
    void confirmCycleDayChange(int oldDay,int next,Runnable cancel,Runnable accepted){if(next==oldDay)return;boolean backward=next<oldDay;String message=backward?"Moving from day "+oldDay+" back to day "+next+" will erase saved check-ins and confirmations from day "+next+" onward through today. This cannot be undone.":"Moving from day "+oldDay+" forward to day "+next+" will skip days. Those skipped actions will be shown as missed.";new AlertDialog.Builder(this).setTitle("Confirm cycle-day change").setMessage(message).setNegativeButton("Cancel",(dialog,which)->{if(cancel!=null)cancel.run();}).setPositiveButton("Confirm",(dialog,which)->{if(backward){LocalDate cutoff=State.careDate().minusDays(oldDay-next);State.clearDateRange(this,cutoff,State.careDate());}else State.markSkippedCycleDays(this,oldDay+1,next-1);State.p(this).edit().putInt("anchorDay",next).putLong("anchor",System.currentTimeMillis()).apply();ReminderReceiver.schedule(this);HrtBuddyWidget.refresh(this);if(accepted!=null)accepted.run();}).show();}
    void showDayOverride(){ base(); TextView h=tv("Adjust cycle day",30); h.setTypeface(null,1); root.addView(h); root.addView(tv("Use this if your real cycle has shifted. The change affects the current cycle record.",15)); int oldDay=State.day(this); NumberPicker e=wheel("Cycle day",1,State.cycle(this),oldDay); gap(12); Button b=button("Review change"); b.setTextColor(purple); b.setOnClickListener(v->{int next=e.getValue();if(next==oldDay){showDashboard();return;}confirmCycleDayChange(oldDay,next,()->{},()->showDashboard());}); root.addView(b); gap(8); Button c=button("Cancel"); c.setOnClickListener(v->showDashboard()); root.addView(c); }
